405	                            timingOk.incrementAndGet();
406	                        } else {
407	                            raceService.sealRace(RACE, new SealRaceRequest(3, "req-seal-" + index));
408	                            sealOk.incrementAndGet();
409	                        }
410	                    } catch (ConflictException ex) {
411	                        conflicts.incrementAndGet();
412	                    }
413	                    return null;
414	                }));
