package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Positive;
import jakarta.validation.constraints.Size;

/**
 * 更换计时芯片请求（选手未冲线前可申请，需裁判确认）。
 *
 * @param replacementId 更换记录ID，全局唯一
 * @param oldChipCode   旧芯片代码（必须与选手当前芯片一致）
 * @param newChipCode   新芯片代码（不得当前绑定在其他未完赛选手名下）
 * @param effectiveAtMs UTC 生效时刻（毫秒）；不得早于已接收分段读数时刻，左闭右开边界
 * @param referee       裁判确认人（操作者账号）
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId     全局唯一请求ID（幂等键）
 */
public record ReplaceChipRequest(
        @NotBlank String replacementId,
        @NotBlank @Size(max = 128) String oldChipCode,
        @NotBlank @Size(max = 128) String newChipCode,
        @NotNull @Positive Long effectiveAtMs,
        @NotBlank @Size(max = 128) String referee,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 选手退赛请求；退赛后不得再提交读数或更换芯片，榜单状态为 WITHDRAWN。
 *
 * @param referee         退赛操作裁判（操作者账号），参与幂等指纹
 * @param expectedVersion 客户端所见赛事版本
 * @param requestId       全局唯一请求ID（幂等键）
 */
public record WithdrawRunnerRequest(
        @NotBlank @Size(max = 128) String referee,
        @NotNull Integer expectedVersion,
        @NotBlank String requestId
) {
}

package com.example.starter.race.api;

import com.fasterxml.jackson.annotation.JsonInclude;

/**
 * 单条分段读数在某次芯片更换重算前后的归属明细（诊断/历史用）。
 *
 * @param timingId       分段记录ID
 * @param checkpointCode 检查点代码
 * @param position       检查点顺序
 * @param elapsedMillis  通过累计耗时（毫秒）
 * @param readAtMs       读数已接收时刻（UTC 毫秒：实际上报时刻优先，否则为服务端接收时刻）
 * @param chipCode       该读数在对应时间线下归属的芯片代码；无法唯一归属为 null
 */
@JsonInclude(JsonInclude.Include.NON_NULL)
public record ChipAttributionItem(
        String timingId,
        String checkpointCode,
        int position,
        long elapsedMillis,
        long readAtMs,
        String chipCode
) {
}

